<script>
	// ConeGlyph — the cone of two J-lens vectors, drawn in their own plane (chapter 4 of
	// *Poised to speak*). The cone {c_s v_s + c_u v_u : c_s, c_u ≥ 0} is hatched with hairline
	// rules in covector ink (it is generated by covectors, read as directions of the stream);
	// its two edges run to the rim as hairlines, and the vectors themselves end, at their true
	// length, in the covector's bar tip. Optional: the plane's disc of radius R (the span, which
	// a subspace would fill), the ghosts −v_s and −v_u (in the span, not in the cone), the
	// edges of the polar cone (dotted: beyond them the nearest point is the apex), and a point
	// p of the plane with its nearest point q on the cone (value ink).
	// Geometry from cone.js (planeOf, nearestInPlane); `P(u, v)` maps plane coordinates to
	// the screen (a flat view, or the axonometric view of fig-j-cone), so the same glyph is
	// drawn in a figure's 3-D view, in small multiples, and in its key.
	import { hatchCone, polarEdges } from './cone.js';
	import { showChar } from '#figures/primitives/scales.js';

	let {
		plane,
		R = 1,
		P = (u, v) => [u, -v],
		chars = null,
		disc = false,
		ghost = false,
		polar = false,
		hatch = 9,
		tip = 2.4,
		labels = true,
		p = null,
		q = null,
		strong = false,
		muted = false,
		labelSize = 13
	} = $props();

	const a = $derived(plane.a), b = $derived(plane.b);
	const unit = (v) => { const n = Math.hypot(v[0], v[1]) || 1; return [v[0] / n, v[1] / n]; };
	const ua = $derived(unit(a)), ub = $derived(unit(b));
	const pt = (u) => P(u[0], u[1]);
	const O = $derived(P(0, 0));
	const rim = (d) => pt([d[0] * R, d[1] * R]);
	const rules = $derived(hatchCone(plane, R, R / hatch));
	const pol = $derived(polarEdges(plane));
	const discPath = $derived.by(() => {
		if (!disc) return '';
		const pts = Array.from({ length: 73 }, (_, i) => pt([R * Math.cos((i * Math.PI) / 36), R * Math.sin((i * Math.PI) / 36)]));
		return 'M' + pts.map((z) => `${z[0].toFixed(2)} ${z[1].toFixed(2)}`).join(' L') + ' Z';
	});
	// a covector's bar tip: a short bar across the (projected) direction, at the tip
	function bar(v) {
		const T = pt(v), d = [T[0] - O[0], T[1] - O[1]], n = Math.hypot(d[0], d[1]) || 1;
		const nx = -d[1] / n, ny = d[0] / n, L = tip * 1.9;
		return { x1: T[0] - nx * L, y1: T[1] - ny * L, x2: T[0] + nx * L, y2: T[1] + ny * L, T, dx: d[0] / n, dy: d[1] / n };
	}
	const bars = $derived([bar(a), bar(b)]);
	// a label beyond the end of a ray (the vector's tip, or the rim if the tip is near it)
	function labelAt(v, dir, extra = 0) {
		const r = Math.max(Math.hypot(v[0], v[1]), 0) ;
		const T = pt([dir[0] * (r + extra), dir[1] * (r + extra)]);
		return T;
	}
</script>

<g class="cone" class:cone--strong={strong} class:cone--muted={muted}>
	{#if disc}<path class="cone__disc" d={discPath} />{/if}
	{#if polar}
		{#each [pol.s, pol.u] as d, k (k)}
			{@const E = rim(d)}
			<line class="cone__polar" x1={O[0]} y1={O[1]} x2={E[0]} y2={E[1]} />
		{/each}
	{/if}
	{#if ghost}
		{#each [ua, ub] as d, k (k)}
			{@const E = rim([-d[0], -d[1]])}
			<line class="cone__ghost" x1={O[0]} y1={O[1]} x2={E[0]} y2={E[1]} />
		{/each}
	{/if}
	<g class="cone__hatch">
		{#each rules as [s0, s1], k (k)}
			{@const A = pt(s0)}
			{@const B = pt(s1)}
			<line x1={A[0]} y1={A[1]} x2={B[0]} y2={B[1]} />
		{/each}
	</g>
	{#each [ua, ub] as d, k (k)}
		{@const E = rim(d)}
		<line class="cone__edge" x1={O[0]} y1={O[1]} x2={E[0]} y2={E[1]} />
	{/each}
	{#each bars as bb, k (k)}
		<line class="cone__vec" x1={O[0]} y1={O[1]} x2={bb.T[0]} y2={bb.T[1]} />
		<line class="cone__bar" x1={bb.x1} y1={bb.y1} x2={bb.x2} y2={bb.y2} />
	{/each}
	<circle class="cone__apex" cx={O[0]} cy={O[1]} r="1.4" />
	{#if q}
		{@const Q = pt(q)}
		{#if p}
			{@const Pp = pt(p)}
			{#if Math.hypot(Pp[0] - Q[0], Pp[1] - Q[1]) > 0.5}
				<line class="cone__gap" x1={Pp[0]} y1={Pp[1]} x2={Q[0]} y2={Q[1]} />
			{/if}
			<circle class="cone__p" cx={Pp[0]} cy={Pp[1]} r={Math.max(1.6, tip * 0.9)} />
		{/if}
		<circle class="cone__q" cx={Q[0]} cy={Q[1]} r={Math.max(1.6, tip * 0.9)} />
	{/if}
	{#if labels && chars}
		{#each [[a, ua], [b, ub]] as [v, d], k (k)}
			{@const L = labelAt(v, d, (R * 0.09))}
			<text class="cone__label" x={L[0]} y={L[1] + labelSize * 0.35} text-anchor="middle" font-size={labelSize}><tspan class="cone__v">v</tspan><tspan class="cone__sub" dy={labelSize * 0.28} font-size={labelSize * 0.82}>{showChar(chars[k])}</tspan></text>
		{/each}
		{#if ghost}
			{#each [ua, ub] as d, k (k)}
				{@const G = rim([-d[0] * 0.86, -d[1] * 0.86])}
				<text class="cone__label cone__label--ghost" x={G[0]} y={G[1] - 5} text-anchor="middle" font-size={labelSize * 0.9}>−<tspan class="cone__v">v</tspan><tspan class="cone__sub" dy={labelSize * 0.26} font-size={labelSize * 0.75}>{showChar(chars[k])}</tspan></text>
			{/each}
		{/if}
	{/if}
</g>

<style>
	.cone { mix-blend-mode: var(--overprint); }
	.cone__disc { fill: none; stroke: var(--rule); stroke-width: var(--hair); }
	.cone__polar { stroke: var(--ink-3); stroke-width: var(--hair); stroke-dasharray: 1 2.5; }
	.cone__ghost { stroke: var(--ink-3); stroke-width: var(--hair); stroke-dasharray: 4 3; }
	.cone__hatch line { stroke: var(--covector); stroke-width: var(--hair); opacity: 0.85; }
	.cone__edge { stroke: var(--covector); stroke-width: var(--hair); }
	.cone__vec { stroke: var(--covector); stroke-width: var(--line); }
	.cone__bar { stroke: var(--covector); stroke-width: 2.2px; stroke-linecap: butt; }
	.cone--strong .cone__vec { stroke-width: 1.6px; }
	.cone__apex { fill: var(--ink-3); }
	.cone__gap { stroke: var(--value); stroke-width: var(--hair); stroke-dasharray: 2 2; }
	.cone__p { fill: var(--paper); stroke: var(--value); stroke-width: 1px; }
	.cone__q { fill: var(--value); }
	.cone__label { font-family: var(--serif); fill: var(--covector-deep); }
	.cone__v { font-style: italic; }
	.cone__label--ghost { fill: var(--ink-3); }
	.cone--muted .cone__hatch line, .cone--muted .cone__edge, .cone--muted .cone__vec, .cone--muted .cone__bar { stroke: var(--ink-3); opacity: 0.55; }
	.cone--muted .cone__q { fill: var(--ink-3); }
	.cone--muted .cone__p { stroke: var(--ink-3); }
</style>
